// RN-10 — slugs (stores, categories) are generated by the application from the
// name, here and only here (database.md: unit-testable normalization, no
// trigger). Lowercase ASCII letters and digits joined by single hyphens:
// accents are stripped, a few letters without a decomposition are spelled
// out, everything else separates words. An empty result means the name has
// nothing to build a slug from — the caller rejects it.
const SPELLED: Record<string, string> = { ß: 'ss', æ: 'ae', ø: 'o', œ: 'oe', đ: 'd', ł: 'l', þ: 'th' };

export function slugify(name: string): string {
  return name
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[ßæøœđłþ]/g, (char) => SPELLED[char] ?? '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
